#!/usr/bin/env python3
"""Validate CI shard ownership and checksums, then build the unified research report."""
import argparse
import json
from pathlib import Path
import shutil
import tarfile
import re

from run_campaign import atomic_json, digest, write_report, TAG
from analyze_pacing_research import analyze


def extract_archive(path, destination):
    # Artifacts are generated by this workflow, but still reject path escape,
    # devices and links before extracting.
    with tarfile.open(path, 'r:gz') as archive:
        for member in archive.getmembers():
            target = (destination / member.name).resolve()
            if not target.is_relative_to(destination.resolve()) or not (member.isfile() or member.isdir()):
                raise ValueError(f'Unsafe archive member: {member.name}')
        archive.extractall(destination, filter='data')


def merge(inputs, out, shard_count, commit, run_url, allow_incomplete=False):
    out.mkdir(parents=True, exist_ok=True)
    expected_names = {f'shard-{i}' for i in range(shard_count)}
    present = {p.name for p in inputs.iterdir() if p.is_dir() and p.name.startswith('shard-')}
    if present - expected_names or (present != expected_names and not allow_incomplete):
        raise ValueError(f'Missing or unexpected shards: expected {shard_count}, present {sorted(present)}')
    manifest = None
    binaries, seen, results, provenance = set(), set(), {}, []
    for name in sorted(present, key=lambda n:int(n.split('-')[1])):
        folder = inputs / name
        shard = json.loads((folder / 'shard.json').read_text(encoding='utf-8'))
        frozen = json.loads((folder / 'frozen.json').read_text(encoding='utf-8'))
        current = json.loads((folder / 'experiment.json').read_text(encoding='utf-8'))
        if manifest is None:
            manifest = current
            shutil.copy2(folder / 'experiment.json', out / 'experiment.json')
        if current != manifest or frozen['commit'] != commit or shard['commit'] != commit:
            raise ValueError(f'{name}: mixed config or source commit')
        if frozen['manifest_sha256'] != digest(folder / 'experiment.json') or shard['manifest_sha256'] != frozen['manifest_sha256']:
            raise ValueError(f'{name}: manifest checksum mismatch')
        if shard['shard_count'] != shard_count or shard['shard_index'] != int(name.split('-')[1]):
            raise ValueError(f'{name}: shard identity mismatch')
        all_cases = [(g, r) for r in range(1, manifest['repeats']+1) for g in manifest['g_hundredths']]
        assigned = {f'g{g:04d}-r{r:02d}' for index, (g, r) in enumerate(all_cases)
                    if index % shard_count == shard['shard_index']}
        if set(shard['expected_cases']) != assigned:
            raise ValueError(f'{name}: shard case list disagrees with matrix')
        found = {p.parent.name for p in (folder / 'runs').glob('*/config.json')}
        if found - assigned or (found != assigned and not allow_incomplete):
            raise ValueError(f'{name}: incomplete or unassigned cases')
        binaries.add(frozen['binary_sha256'])
        provenance.append(dict(name=name, frozen=frozen))
        for case_id in sorted(found):
            if case_id in seen:
                raise ValueError(f'Duplicate case: {case_id}')
            source = folder / 'runs' / case_id
            if allow_incomplete and not all((source / filename).exists() for filename in ('summary.json', 'artifact_integrity.json')):
                continue
            case = json.loads((source / 'config.json').read_text(encoding='utf-8'))
            result = json.loads((source / 'summary.json').read_text(encoding='utf-8'))
            integrity = json.loads((source / 'artifact_integrity.json').read_text(encoding='utf-8'))
            if case['commit'] != commit or case['binary_sha256'] != frozen['binary_sha256']:
                raise ValueError(f'{case_id}: case provenance mismatch')
            for field in ('state_log', 'packet_rtt_file'):
                if field in integrity and digest(source / case[field]) != integrity[field]['compressed_sha256']:
                    raise ValueError(f'{case_id}: corrupt {field}')
            destination = out / 'runs' / case_id
            if destination.exists():
                raise ValueError(f'Output already has {case_id}; use a fresh merge directory')
            shutil.copytree(source, destination)
            seen.add(case_id)
            results[case_id] = result
    if not manifest or len(binaries) != 1:
        raise ValueError('No shards or shards do not use the same preflight binary')
    if not allow_incomplete and len(seen) != manifest['expected_runs']:
        raise ValueError('Recorded case count does not match expected_runs')
    atomic_json(out / 'ci_provenance.json', dict(commit=commit, run_url=run_url,
                binary_sha256=next(iter(binaries)), shards=provenance,
                complete_dataset=not allow_incomplete, recorded_cases=len(seen)))
    analyze(out, out / 'analysis', allow_incomplete)
    write_report(out, manifest, results)
    with (out / 'report.md').open('a', encoding='utf-8') as report:
        report.write(f'\nGitHub Actions: {run_url}\n\n实验 commit：`{commit}`。全部数据来自 Linux 虚拟网络，未混入 Windows 本地结果。\n')
    finalize(out, commit, run_url)
    return dict(recorded=len(seen), tag=TAG)


def finalize(out, commit, run_url):
    audit = json.loads((out / 'analysis/analysis_audit.json').read_text(encoding='utf-8'))
    index = {str(p.relative_to(out)):digest(p) for p in out.rglob('*')
             if p.is_file() and p.name not in ('data-index.json', 'tag-message.txt')}
    atomic_json(out / 'data-index.json', dict(files=index, commit=commit, run_url=run_url))
    (out / 'tag-message.txt').write_text(f'SCP always-slow-start pacing g sweep\n'
        f'1 GiB, 1000 Mbps/direction, fixed base RTT 100 ms, loss 0.\n'
        f'Recorded cases: {audit["recorded_configs"]}; complete: {audit["statuses"].get("complete", 0)}.\n'
        f'CI run and data artifacts: {run_url}\nSource: {commit}\n'
        f'Data index SHA256: {digest(out / "data-index.json")}\n', encoding='utf-8')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('downloads', type=Path, nargs='?')
    parser.add_argument('--out', type=Path, required=True)
    parser.add_argument('--shards', type=int, default=16)
    parser.add_argument('--commit', required=True)
    parser.add_argument('--run-url', required=True)
    parser.add_argument('--allow-incomplete', action='store_true')
    parser.add_argument('--finalize', action='store_true', help='Add final baseline checks to the checksum index')
    args = parser.parse_args()
    if args.finalize:
        finalize(args.out, args.commit, args.run_url)
        raise SystemExit(0)
    if args.downloads is None:
        parser.error('downloads is required unless --finalize is used')
    extracted = args.downloads / 'extracted'
    extracted.mkdir(exist_ok=True)
    selected = {}
    for archive in sorted(args.downloads.rglob('shard-*-inputs.tar.gz')):
        name = archive.name.removesuffix('-inputs.tar.gz')
        match = re.search(r'attempt-(\d+)$', archive.parent.name)
        attempt = int(match.group(1)) if match else 0
        if name in selected and selected[name][0] == attempt:
            raise ValueError(f'Duplicate archive for {name}, attempt {attempt}')
        if name not in selected or attempt > selected[name][0]:
            selected[name] = attempt, archive
    for attempt, archive in selected.values():
        extract_archive(archive, extracted)
    print(json.dumps(merge(extracted, args.out, args.shards, args.commit, args.run_url, args.allow_incomplete)))
